const body = $input.first().json.body || $input.first().json;
const applicant = {
  name: body.name || '',
  email: body.email || '',
  phone: body.phone || '',
  position: body.position || '',
  resumeText: body.resume_text || '',
  appliedAt: new Date().toISOString()
};
return [{ json: applicant }];

const input = $input.first().json;
const screening = JSON.parse(input.message?.content || '{}');
const applicant = $('Parse Resume Data').first().json;
return [{
  json: {
    ...applicant,
    relevanceScore: screening.relevance_score || 0,
    keySkills: (screening.key_skills || []).join(', '),
    experienceYears: screening.experience_years || 0,
    recommendation: screening.recommendation || 'review',
    screeningSummary: screening.summary || '',
    screenedAt: new Date().toISOString()
  }
}];
